end
= Route104_MrBrineysHouse_EventScript_Briney
lock
faceplayer
call_if_unset FLAG_MR_BRINEY_SAILING_INTRO Route104_MrBrineysHouse_EventScript_SailingIntro
goto_if_unset FLAG_DELIVERED_STEVEN_LETTER Route104_MrBrineysHouse_EventScript_SailBothDeliveries
goto_if_unset FLAG_DELIVERED_DEVON_GOODS Route104_MrBrineysHouse_EventScript_SailDeliverPackage
goto Route104_MrBrineysHouse_EventScript_WhereAreWeBound
end
= Route104_MrBrineysHouse_EventScript_WhereAreWeBound
msgbox	MR. BRINEY: Ahoi! Für dich fahr ich jederzeit aufs Meer hinaus!Und, mein Freund, wohin soll die Reise gehen?
waitmessage
multichoicedefault 20 8 MULTI_BRINEY_OFF_DEWFORD 1 FALSE
switch VAR_RESULT
case 0 Route104_MrBrineysHouse_EventScript_SailToDewford
case 1 Route104_MrBrineysHouse_EventScript_DeclineSailing
case MULTI_B_PRESSED Route104_MrBrineysHouse_EventScript_DeclineSailing
end
= Route104_MrBrineysHouse_EventScript_DeclineSailing
msgbox	MR. BRINEY: Ach, wirklich? Nun, PEEKO verdankt dir ihr Leben.Sag mir einfach Bescheid, wann immer du in See stechen möchtest!
release
end
= Route104_MrBrineysHouse_EventScript_SailToDewford
msgbox	MR. BRINEY: Also DEWFORD!Anker lichten! PEEKO, wir stechen in See, mein Schatz!
call EventScript_BackupMrBrineyLocation
setvar VAR_BOARD_BRINEY_BOAT_STATE 1
clearflag FLAG_HIDE_ROUTE_104_MR_BRINEY
setflag FLAG_HIDE_BRINEYS_HOUSE_MR_BRINEY
setflag FLAG_HIDE_BRINEYS_HOUSE_PEEKO
setvar VAR_RUSTBORO_CITY_STATE 8
setvar VAR_ROUTE104_STATE 2
setflag FLAG_HIDE_RUSTBORO_CITY_RIVAL
setflag FLAG_HIDE_ROUTE_104_RIVAL
warp Route104 13 51
waitstate
releaseall
end
= Route104_MrBrineysHouse_EventScript_SailDeliverPackage
msgboxyesno	MR. BRINEY: Ahoy! I know exactly what you want to say!You're to deliver a package to CAPT. STERN in SLATEPORT.What you need me to do is no problem at all--I'm the man for the job!First, we'll set sail for DEWFORD.
goto_if_eq VAR_RESULT NO Route104_MrBrineysHouse_EventScript_DeclineDeliverySailing
goto Route104_MrBrineysHouse_EventScript_SailToDewford
end
= Route104_MrBrineysHouse_EventScript_DeclineDeliverySailing
msgbox	MR. BRINEY: Ach, wirklich? Deine Lieferungen können warten?Sag mir einfach Bescheid, wann immer du in See stechen möchtest!
release
end
= Route104_MrBrineysHouse_EventScript_SailBothDeliveries
msgboxyesno	MR. BRINEY: Ahoy! I know exactly what you want to say!You're to deliver a LETTER to DEWFORD and a package to SLATEPORT.What you need me to do is no problem at all--I'm the man for the job!First, we'll set sail for DEWFORD.
goto_if_eq VAR_RESULT NO Route104_MrBrineysHouse_EventScript_DeclineDeliverySailing
goto Route104_MrBrineysHouse_EventScript_SailToDewford
end
= Route104_MrBrineysHouse_EventScript_SailingIntro
setflag FLAG_MR_BRINEY_SAILING_INTRO
msgbox	MR. BRINEY: Warte, mein Mädchen! Warte auf mich, PEEKO!
msgboxyesno	Hm? You're PLAYER! You saved my darling PEEKO! We owe so much to you!What's that? You want to sail with me?Hmhm…You have a LETTER bound for DEWFORD and a package for SLATEPORT, then?Quite the busy life you must lead!But, certainly, what you're asking is no problem at all.You've come to the right man! We'll set sail for DEWFORD.
goto_if_eq VAR_RESULT NO Route104_MrBrineysHouse_EventScript_DeclineDeliverySailing
goto Route104_MrBrineysHouse_EventScript_SailToDewford
end
